 * This project uses @Incubating APIs which are subject to change.
 */

pluginManagement {
    repositories {
        google()
        mavenCentral()
        gradlePluginPortal()
    }
}

dependencyResolutionManagement {
    repositories {
        google()
        mavenCentral()
        maven("https://jitpack.io")
    }
}

plugins {
    // Apply the foojay-resolver plugin to allow automatic download of JDKs
    id("org.gradle.toolchains.foojay-resolver-convention") version "0.8.0"
}

rootProject.name = "updater"
include("core")

// The Android app needs an SDK at configuration time, which a machine running only
// `:core:test` has no reason to carry, so it joins the build only when one is present.
val hasAndroidSdk =
    System.getenv("ANDROID_HOME") != null ||
        System.getenv("ANDROID_SDK_ROOT") != null ||
        file("local.properties").takeIf { it.isFile }?.readText()?.contains("sdk.dir") == true

if (hasAndroidSdk) {
    include("android")
} else {
    println("No Android SDK found, so the :android module is not in this build.")
    println("Set ANDROID_HOME (or write sdk.dir into local.properties) to build it.")
}
